args.script:
(() => {
  const results = [...document.querySelectorAll('li.arxiv-result')].slice(0,5).map((li, i) => ({
    index: i+1,
    id: li.querySelector('p.list-title a')?.textContent.trim(),
    title: li.querySelector('p.title')?.textContent.trim().replace(/\s+/g,' '),
    authors: [...li.querySelectorAll('p.authors a')].map(a=>a.textContent.trim()),
    announced: li.querySelector('p.is-size-7')?.textContent.trim().replace(/\s+/g,' '),
    abstract: li.querySelector('span.abstract-full')?.textContent.trim().replace(/\s+/g,' ').slice(0,500)
  }));
  return {url: location.href, results};
})()
